// Me: sentences built from your answers
const ADJ_TL = { disciplined: 'disiplinado', curious: 'mausisa', kind: 'mabait', funny: 'nakakatawa', 'a natural leader': 'likas na lider', creative: 'malikhain',
  resilient: 'matatag', brave: 'matapang', grateful: 'mapagpasalamat', focused: 'nakatutok', 'still discovering yourself': 'kinikilala pa ang sarili' };
const ADJ_ALT = Object.keys(ADJ_TL).join('|');
const listTL = (t, s, f) => { const a = s.split(/, | and /).map(f); return a.length <= 1 ? a.join('') : `${a.slice(0, -1).join(', ')} at ${a[a.length - 1]}`; };
patterns.unshift(
  [new RegExp(`^(.+) — ((?:${ADJ_ALT})(?:(?:, | and )(?:${ADJ_ALT}))*)(?:\\. You live for (.+))?\\.$`), (t, n, adj, vals) => `${n} — ${listTL(t, adj, (x) => ADJ_TL[x] || x)}${vals ? `. Nabubuhay ka para sa ${listTL(t, vals, (x) => low(t, x))}` : ''}.`],
  [/^(\d+) min exercise a day$/, '$1 min na ehersisyo kada araw'],
  [/^([\d.]+)h sleep$/, '$1 oras na tulog'],
  [/^(.+) a day$/, '$1 kada araw'],
  [/^You say (.+) matters to you, but it barely shows in your days \((.+)\)\. What’s one small thing you could do for it today\?$/, (t, a, b) => `Sinasabi mong mahalaga ang ${low(t, a)}, pero halos hindi ito makita sa mga araw mo (${t(b)}). Ano ang isang maliit na magagawa mo para dito ngayon?`],
);

